<?php
declare(strict_types=1); namespace Hls\Controllers;
use Hls\Http\View;use Hls\Http\Input;use Hls\Http\HttpError;use Hls\Repositories\Repository;use Hls\Middleware\Access;use Hls\Services\Audit;
final class FinancePayableController{public function __construct(private Repository $repo,private View $view,private Access $access,private Audit $audit){}private function scope():array{return[$this->access->user['id'],$this->access->user['all_branches']];} public function index():void{$this->access->demand('finance.payable.view');$rows=$this->repo->all('SELECT b.*,s.name supplier_name,br.name branch_name FROM fin_supplier_bills b JOIN md_suppliers s ON s.id=b.supplier_id JOIN branches br ON br.id=b.branch_id WHERE b.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) ORDER BY b.id DESC',$this->scope());$suppliers=$this->repo->all('SELECT id,name,branch_id FROM md_suppliers WHERE active=1');$branches=$this->repo->all('SELECT id,code,name FROM branches WHERE active=1');$this->view->render('finance-payables',['title'=>'Utang','rows'=>$rows,'suppliers'=>$suppliers,'branches'=>$branches,'error'=>null]);} public function save():void{$this->access->demand('finance.payable.create');$branch=Input::id($_POST,'branch_id');$this->access->demandBranch($branch);$supplier=Input::id($_POST,'supplier_id');$ref=trim((string)($_POST['bill_ref']??''));$date=Input::text($_POST,'bill_date',10);$due=Input::text($_POST,'due_date',10,false);$ds=$_POST['description']??[];$qs=$_POST['quantity']??[];$ps=$_POST['unit_price']??[];if(!is_array($ds)||!is_array($qs)||!is_array($ps))throw new HttpError(422,'Item tidak valid.');$lines=[];$total=0;foreach($ds as $i=>$d){$d=trim((string)$d);$q=(float)($qs[$i]??0);$p=(float)($ps[$i]??-1);if($d===''&&$q==0&&$p==0)continue;if($d===''||$q<=0||$p<0)throw new HttpError(422,'Item tidak valid.');$sub=round($q*$p,2);$lines[]=[$d,$q,$p,$sub];$total=round($total+$sub,2);}if(!$lines||$total<=0)throw new HttpError(422,'Minimal satu item diperlukan.');if($ref===''||!$this->repo->one('SELECT id FROM md_suppliers WHERE id=? AND branch_id=? AND active=1',[$supplier,$branch]))throw new HttpError(422,'Supplier atau referensi tidak valid.');$this->repo->db->beginTransaction();try{$this->repo->run('INSERT INTO fin_supplier_bills(branch_id,supplier_id,bill_ref,bill_date,due_date,status,subtotal,total_amount,created_by,created_at,updated_at) VALUES(?,?,?,?,?,"DRAFT",?,?,?,NOW(),NOW())',[$branch,$supplier,$ref,$date,$due?:null,$total,$total,$this->access->user['id']]);$id=(int)$this->repo->db->lastInsertId();foreach($lines as $l)$this->repo->run('INSERT INTO fin_supplier_bill_lines(bill_id,description,quantity,unit_price,line_total,created_at) VALUES(?,?,?,?,?,NOW())',[$id,...$l]);$this->repo->db->commit();$this->audit->record((int)$this->access->user['id'],'finance_supplier_bill_created','fin_supplier_bills',$id,['total'=>$total,'lines'=>count($lines)]);$this->view->redirect('/finance/payables');}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}} public function edit():void{$this->access->demand('finance.payable.create');$id=Input::id($_GET,'id');$row=$this->repo->one('SELECT b.*,s.name supplier_name,br.name branch_name FROM fin_supplier_bills b JOIN md_suppliers s ON s.id=b.supplier_id JOIN branches br ON br.id=b.branch_id WHERE b.id=?',[$id]);if(!$row||!$this->access->branch((int)$row['branch_id']))throw new HttpError(404,'Tagihan tidak ditemukan.');if($row['status']!=='DRAFT')throw new HttpError(409,'Hanya tagihan DRAFT yang dapat diedit.');$items=$this->repo->all('SELECT * FROM fin_supplier_bill_lines WHERE bill_id=? ORDER BY id',[$id]);$suppliers=$this->repo->all('SELECT id,name,branch_id FROM md_suppliers WHERE active=1 AND branch_id=?',[$row['branch_id']]);$branches=$this->repo->all('SELECT id,code,name FROM branches WHERE active=1');$this->view->render('finance-payable-edit',['title'=>'Edit Utang','row'=>$row,'items'=>$items,'suppliers'=>$suppliers,'branches'=>$branches,'error'=>null]);}
 public function update():void{$this->access->demand('finance.payable.create');$id=Input::id($_POST,'id');$branch=Input::id($_POST,'branch_id');$supplier=Input::id($_POST,'supplier_id');$ref=trim((string)($_POST['bill_ref']??''));$date=Input::text($_POST,'bill_date',10);$due=Input::text($_POST,'due_date',10,false);$ds=$_POST['description']??[];$qs=$_POST['quantity']??[];$ps=$_POST['unit_price']??[];if(!$this->access->branch($branch)||!is_array($ds)||!is_array($qs)||!is_array($ps))throw new HttpError(422,'Data tagihan tidak valid.');$lines=[];$total=0;foreach($ds as $i=>$d){$d=trim((string)$d);$q=(float)($qs[$i]??0);$p=(float)($ps[$i]??-1);if($d===''&&$q==0&&$p==0)continue;if($d===''||$q<=0||$p<0)throw new HttpError(422,'Item tidak valid.');$sub=round($q*$p,2);$lines[]=[$d,$q,$p,$sub];$total=round($total+$sub,2);}if(!$lines||$total<=0||$ref==='')throw new HttpError(422,'Minimal satu item dan referensi wajib diisi.');if(!$this->repo->one('SELECT id FROM md_suppliers WHERE id=? AND branch_id=? AND active=1',[$supplier,$branch]))throw new HttpError(422,'Supplier tidak valid.');$this->repo->db->beginTransaction();try{$row=$this->repo->one('SELECT * FROM fin_supplier_bills WHERE id=? FOR UPDATE',[$id]);if(!$row||!$this->access->branch((int)$row['branch_id']))throw new HttpError(404,'Tagihan tidak ditemukan.');if($row['status']!=='DRAFT')throw new HttpError(409,'Tagihan sudah diposting dan tidak dapat diedit.');if((int)$row['branch_id']!==$branch)throw new HttpError(422,'Cabang tagihan tidak dapat diubah.');$this->repo->run('UPDATE fin_supplier_bills SET supplier_id=?,bill_ref=?,bill_date=?,due_date=?,subtotal=?,total_amount=?,updated_at=NOW() WHERE id=?',[$supplier,$ref,$date,$due?:null,$total,$total,$id]);$this->repo->run('DELETE FROM fin_supplier_bill_lines WHERE bill_id=?',[$id]);foreach($lines as $l)$this->repo->run('INSERT INTO fin_supplier_bill_lines(bill_id,description,quantity,unit_price,line_total,created_at) VALUES(?,?,?,?,?,NOW())',[$id,...$l]);$this->repo->db->commit();$this->audit->record((int)$this->access->user['id'],'finance_supplier_bill_updated','fin_supplier_bills',$id,['total'=>$total,'lines'=>count($lines)]);$this->view->redirect('/finance/payable-detail?id='.$id);}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}} public function post():void{$this->access->demand('finance.payable.post');$id=Input::id($_POST,'id');$this->repo->db->beginTransaction();try{$row=$this->repo->one('SELECT * FROM fin_supplier_bills WHERE id=? FOR UPDATE',[$id]);if(!$row||!$this->access->branch((int)$row['branch_id']))throw new HttpError(404,'Tagihan tidak ditemukan.');if($row['status']!=='DRAFT')throw new HttpError(409,'Tagihan hanya dapat diposting dari status DRAFT.');if(!$this->repo->one('SELECT id FROM md_suppliers WHERE id=? AND branch_id=? AND active=1',[$row['supplier_id'],$row['branch_id']]))throw new HttpError(422,'Supplier tidak aktif atau tidak sesuai cabang.');$items=$this->repo->all('SELECT quantity,unit_price,line_total FROM fin_supplier_bill_lines WHERE bill_id=? FOR UPDATE',[$id]);if(!$items)throw new HttpError(422,'Tagihan harus memiliki item.');$total=0;foreach($items as $item){$q=(float)$item['quantity'];$p=(float)$item['unit_price'];if($q<=0||$p<0)throw new HttpError(422,'Item tagihan tidak valid.');$total=round($total+round($q*$p,2),2);}if($total<=0)throw new HttpError(422,'Total tagihan tidak valid.');$this->repo->run('UPDATE fin_supplier_bills SET status="POSTED",subtotal=?,total_amount=?,updated_at=NOW(),version=version+1 WHERE id=? AND status="DRAFT"',[$total,$total,$id]);$this->repo->db->commit();$this->audit->record((int)$this->access->user['id'],'finance_supplier_bill_posted','fin_supplier_bills',$id,['total'=>$total,'lines'=>count($items)]);$this->view->redirect('/finance/payable-detail?id='.$id);}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}} public function detail():void{$this->access->demand('finance.payable.view');$id=Input::id($_GET,'id');$row=$this->repo->one('SELECT b.*,s.name supplier_name,br.name branch_name FROM fin_supplier_bills b JOIN md_suppliers s ON s.id=b.supplier_id JOIN branches br ON br.id=b.branch_id WHERE b.id=?',[$id]);if(!$row||!$this->access->branch((int)$row['branch_id']))throw new HttpError(404,'Tagihan tidak ditemukan.');$items=$this->repo->all('SELECT * FROM fin_supplier_bill_lines WHERE bill_id=? ORDER BY id',[$id]);$payments=$this->repo->all('SELECT p.*,a.code account_code FROM fin_supplier_payments p JOIN fin_accounts a ON a.id=p.account_id WHERE p.bill_id=? ORDER BY p.id',[$id]);$total=0;$paid=0;foreach($items as $i)$total=round($total+(float)$i['line_total'],2);foreach($payments as $p)if($p['status']==='POSTED')$paid=round($paid+(float)$p['amount'],2);$accounts=$this->repo->all('SELECT id,code,name FROM fin_accounts WHERE branch_id=? AND active=1 ORDER BY code',[$row['branch_id']]);$this->view->render('finance-payable-detail',['title'=>'Utang','row'=>$row,'items'=>$items,'payments'=>$payments,'total'=>$total,'paid'=>$paid,'remaining'=>max(0,$total-$paid),'accounts'=>$accounts]);}
 public function pay():void{$this->access->demand('finance.payable.pay');$id=Input::id($_POST,'id');$account=Input::id($_POST,'account_id');$date=Input::text($_POST,'payment_date',10);$ref=trim((string)($_POST['payment_ref']??''));$amount=round((float)($_POST['amount']??0),2);$note=trim((string)($_POST['note']??''));if($ref===''||$amount<=0)throw new HttpError(422,'Referensi dan nominal pembayaran wajib valid.');$this->repo->db->beginTransaction();try{$row=$this->repo->one('SELECT * FROM fin_supplier_bills WHERE id=? FOR UPDATE',[$id]);if(!$row||!$this->access->branch((int)$row['branch_id']))throw new HttpError(404,'Tagihan tidak ditemukan.');if(!in_array($row['status'],['POSTED','PARTIALLY_PAID'],true))throw new HttpError(409,'Tagihan belum dapat dibayar.');$acct=$this->repo->one('SELECT id FROM fin_accounts WHERE id=? AND branch_id=? AND active=1',[$account,$row['branch_id']]);if(!$acct)throw new HttpError(422,'Rekening tidak valid.');if($this->repo->one('SELECT id FROM fin_supplier_payments WHERE payment_ref=?',[$ref]))throw new HttpError(409,'Referensi pembayaran sudah digunakan.');$sum=$this->repo->one('SELECT COALESCE(SUM(amount),0) paid FROM fin_supplier_payments WHERE bill_id=? AND status="POSTED"',[$id]);$paid=(float)$sum['paid'];$remaining=round((float)$row['total_amount']-$paid,2);if($amount>$remaining)throw new HttpError(422,'Pembayaran melebihi sisa utang.');$this->repo->run('INSERT INTO fin_supplier_payments(bill_id,branch_id,payment_ref,payment_date,account_id,amount,status,note,created_by,created_at) VALUES(?,?,?,?,?,?,\"POSTED\",?,?,NOW())',[$id,$row['branch_id'],$ref,$date,$account,$amount,$note?:null,$this->access->user['id']]);$pid=(int)$this->repo->db->lastInsertId();$this->repo->run('INSERT INTO fin_cash_ledger(branch_id,account_id,transaction_type,reference_type,reference_id,transaction_date,debit,credit,note,created_by,created_at) VALUES(?, ?,\"PAYMENT\",\"SUPPLIER_PAYMENT\",?,?,0,?,?,?,NOW())',[$row['branch_id'],$account,$pid,$date,$amount,$note?:$ref,$this->access->user['id']]);$newStatus=($amount+ $paid+0.0001 >= (float)$row['total_amount'])?'PAID':'PARTIALLY_PAID';$this->repo->run('UPDATE fin_supplier_bills SET status=?,updated_at=NOW(),version=version+1 WHERE id=?',[$newStatus,$id]);$this->repo->db->commit();$this->audit->record((int)$this->access->user['id'],'finance_supplier_payment_posted','fin_supplier_payments',$pid,['bill_id'=>$id,'amount'=>$amount]);$this->view->redirect('/finance/payable-detail?id='.$id);}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;}}}